package thaumcraft.client;

import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;
import net.neoforged.neoforge.client.extensions.common.RegisterClientExtensionsEvent;
import thaumcraft.registry.R3Content;

@EventBusSubscriber(modid = "thaumcraft", bus = EventBusSubscriber.Bus.MOD, value = Dist.CLIENT)
public final class R3Client {
    @SubscribeEvent public static void crucibleRenderer(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.CRUCIBLE_ENTITY.get(),CrucibleRenderer::new);}
    @SubscribeEvent public static void nodeJarRenderer(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.NODE_JAR_ENTITY.get(),JarredNodeRenderer::new);}
    @SubscribeEvent public static void nodeJarItems(RegisterClientExtensionsEvent event){event.registerItem(new JarredNodeRenderer.Extension(),R3Content.NODE_JAR_ITEM.get());event.registerItem(new AuraNodeItemRenderer.Extension(),thaumcraft.registry.R2Content.AURA_NODE.get().asItem());}
    @SubscribeEvent public static void lamps(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.LAMP_ENTITY.get(),ArcaneLampRenderer::new);}
    @SubscribeEvent public static void eldritchAltar(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.ELDRITCH_ALTAR_ENTITY.get(),EldritchAltarRenderer::new);}
    @SubscribeEvent public static void warpReload(RegisterClientReloadListenersEvent event){event.registerReloadListener((net.minecraft.server.packs.resources.ResourceManagerReloadListener)manager->WarpPostProcessor.reload());}
    @SubscribeEvent public static void mindSpiders(EntityRenderersEvent.RegisterRenderers event){event.registerEntityRenderer(thaumcraft.entities.R3Entities.MIND_SPIDER.get(),MindSpiderRenderer::new);}
    @SubscribeEvent public static void stoneModel(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent event){event.enqueueWork(()->{net.minecraft.client.renderer.item.ItemProperties.register(R3Content.ESSENTIA_PHIAL.get(),net.minecraft.resources.ResourceLocation.parse("thaumcraft:filled"),(stack,level,entity,seed)->R3Content.aspect(stack)==null?0:1);net.minecraft.client.renderer.item.ItemProperties.register(thaumcraft.registry.R3Equipment.SINISTER_STONE.get(),net.minecraft.resources.ResourceLocation.parse("thaumcraft:sinister_active"),(stack,level,entity,seed)->RelicHud.stoneActive(entity)?1:0);});}
    @SubscribeEvent public static void bore(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.BORE_ENTITY.get(),ArcaneBoreRenderer::new);}
    @SubscribeEvent public static void boreScreen(RegisterMenuScreensEvent event){event.register(R3Content.BORE_MENU.get(),ArcaneBoreScreen::new);}
    @SubscribeEvent public static void boreItems(RegisterClientExtensionsEvent event){event.registerItem(new ArcaneBoreRenderer.Extension(),R3Content.BORE_ITEM.get(),R3Content.BORE_BASE_ITEM.get());}
    @SubscribeEvent public static void trunks(EntityRenderersEvent.RegisterRenderers event){event.registerEntityRenderer(thaumcraft.entities.R3Entities.TRUNK.get(),TrunkRenderers.Trunk::new);event.registerBlockEntityRenderer(R3Content.HUNGRY_CHEST_ENTITY.get(),TrunkRenderers.Chest::new);}
    @SubscribeEvent public static void trunkScreen(RegisterMenuScreensEvent event){event.register(R3Content.TRUNK_MENU.get(),TrunkScreen::new);}
    @SubscribeEvent public static void trunkItems(RegisterClientExtensionsEvent event){event.registerItem(new TrunkRenderers.Extension(),R3Content.HUNGRY_CHEST_ITEM.get(),thaumcraft.registry.R3Equipment.TRAVELING_TRUNK.get());}
    @SubscribeEvent public static void golemItemModels(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent event){event.enqueueWork(()->{for(var item:thaumcraft.registry.R3Equipment.GOLEM_BODIES.values()){net.minecraft.client.renderer.item.ItemProperties.register(item.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("thaumcraft","golem_advanced"),(stack,level,entity,seed)->thaumcraft.items.GolemPlacerItem.advanced(stack)?1:0);net.minecraft.client.renderer.item.ItemProperties.register(item.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("thaumcraft","golem_core"),(stack,level,entity,seed)->{var tag=stack.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag();return tag.contains("core")&&tag.getInt("core")>=0?1:0;});}});}
    @SubscribeEvent public static void golems(EntityRenderersEvent.RegisterRenderers event){event.registerEntityRenderer(thaumcraft.entities.R3Entities.GOLEM.get(),GolemRenderer::new);event.registerEntityRenderer(thaumcraft.entities.R3Entities.GOLEM_BOBBER.get(),GolemBobberRenderer::new);event.registerEntityRenderer(thaumcraft.entities.R3Entities.DART.get(),DartRenderer::new);}
    @SubscribeEvent public static void golemLayers(EntityRenderersEvent.RegisterLayerDefinitions event){event.registerLayerDefinition(GolemModel.LAYER,GolemModel::layer);event.registerLayerDefinition(GolemAccessories.LAYER,GolemAccessories::layer);}
    @SubscribeEvent public static void golemScreen(RegisterMenuScreensEvent event){event.register(R3Content.GOLEM_MENU.get(),GolemScreen::new);}
    @SubscribeEvent public static void mirrors(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.MIRROR_ENTITY.get(),MirrorRenderer::new);}
    @SubscribeEvent public static void mirrorScreen(RegisterMenuScreensEvent event){event.register(R3Content.HAND_MIRROR_MENU.get(),HandMirrorScreen::new);}
    @SubscribeEvent public static void focusRenderers(EntityRenderersEvent.RegisterRenderers event){event.registerEntityRenderer(thaumcraft.entities.R3Entities.FOCUS_PROJECTILE.get(),FocusProjectileRenderer::new);event.registerEntityRenderer(thaumcraft.entities.R3Entities.PRIMAL_ORB.get(),FocusProjectileRenderer::new);event.registerEntityRenderer(thaumcraft.entities.R3Entities.FIREBAT.get(),FocusFireBatRenderer::new);event.registerBlockEntityRenderer(R3Content.FOCUS_MEMORY_ENTITY.get(),FocusMemoryRenderer::new);event.registerBlockEntityRenderer(R3Content.FOCAL_ENTITY.get(),FocalManipulatorRenderer::new);}
    @SubscribeEvent public static void focusLayer(EntityRenderersEvent.RegisterLayerDefinitions event){event.registerLayerDefinition(FocusFireBatRenderer.LAYER,FocusFireBatRenderer::layer);}
    @SubscribeEvent public static void focusScreens(RegisterMenuScreensEvent event){event.register(R3Content.FOCAL_MENU.get(),FocalManipulatorScreen::new);event.register(R3Content.POUCH_MENU.get(),FocusPouchScreen::new);}
    @SubscribeEvent public static void brainJarRenderer(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.BRAIN_JAR_ENTITY.get(),BrainJarRenderer::new);}
    @SubscribeEvent public static void crystalRenderer(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.CRYSTAL_CLUSTER_ENTITY.get(),CrystalClusterRenderer::new);}
    @SubscribeEvent public static void crystalItems(RegisterClientExtensionsEvent event){event.registerItem(new CrystalClusterItemRenderer.Extension(),R3Content.CRYSTAL_CLUSTERS.stream().map(block->block.get().asItem()).toArray(net.minecraft.world.item.Item[]::new));}
    @SubscribeEvent public static void jarItems(RegisterClientExtensionsEvent event){event.registerItem(new JarItemRenderer.Extension(),R3Content.WARDED_JAR.get().asItem(),R3Content.VOID_JAR.get().asItem());}
    @SubscribeEvent public static void visItems(RegisterClientExtensionsEvent event){event.registerItem(new VisDeviceItemRenderer.Extension(),R3Content.VIS_RELAY.get().asItem(),R3Content.WORKBENCH_CHARGER.get().asItem(),R3Content.NODE_STABILIZER.get().asItem(),R3Content.ADVANCED_NODE_STABILIZER.get().asItem(),R3Content.NODE_CONVERTER.get().asItem());}
    @SubscribeEvent public static void visRenderers(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(R3Content.VIS_RELAY_ENTITY.get(),VisDeviceRenderers.Relay::new);event.registerBlockEntityRenderer(R3Content.NODE_STABILIZER_ENTITY.get(),VisDeviceRenderers.Stabilizer::new);event.registerBlockEntityRenderer(R3Content.NODE_CONVERTER_ENTITY.get(),VisDeviceRenderers.Converter::new);event.registerBlockEntityRenderer(R3Content.ENERGIZED_NODE_ENTITY.get(),VisDeviceRenderers.Energized::new);event.registerBlockEntityRenderer(R3Content.WAND_PEDESTAL_ENTITY.get(),context->new net.minecraft.client.renderer.blockentity.BlockEntityRenderer<thaumcraft.visnet.WandPedestalBlockEntity>(){private final PedestalRenderer renderer=new PedestalRenderer(context);public void render(thaumcraft.visnet.WandPedestalBlockEntity tile,float partial,com.mojang.blaze3d.vertex.PoseStack pose,net.minecraft.client.renderer.MultiBufferSource buffers,int light,int overlay){renderer.render(tile,partial,pose,buffers,light,overlay);}});}
    @SubscribeEvent public static void reloadModels(RegisterClientReloadListenersEvent event){event.registerReloadListener((net.minecraft.server.packs.resources.ResourceManagerReloadListener)manager->{OriginalObjMesh.clear();PrimalArrowRenderer.reload();});}
    @SubscribeEvent public static void layers(EntityRenderersEvent.RegisterLayerDefinitions event){event.registerLayerDefinition(BellowsRenderer.LAYER,BellowsRenderer::layer);event.registerLayerDefinition(InfusionMatrixRenderer.LAYER,InfusionMatrixRenderer::layer);}
    @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){event.registerEntityRenderer(thaumcraft.entities.R3Entities.BOTTLE_TAINT.get(),net.minecraft.client.renderer.entity.ThrownItemRenderer::new);event.registerEntityRenderer(thaumcraft.entities.R3Entities.ALUMENTUM.get(),net.minecraft.client.renderer.entity.ThrownItemRenderer::new);event.registerBlockEntityRenderer(R3Content.TRANSPORT_ENTITY.get(),EssentiaTransportRenderer::new);event.registerBlockEntityRenderer(R3Content.THAUMATORIUM_ENTITY.get(),ThaumatoriumRenderer::new);event.registerBlockEntityRenderer(R3Content.NITOR_ENTITY.get(),NitorRenderer::new);event.registerBlockEntityRenderer(R3Content.BELLOWS_ENTITY.get(),BellowsRenderer::new);event.registerBlockEntityRenderer(R3Content.PEDESTAL_ENTITY.get(),PedestalRenderer::new);event.registerBlockEntityRenderer(R3Content.INFUSION_ENTITY.get(),InfusionMatrixRenderer::new);}
    @SubscribeEvent public static void setup(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent event){event.enqueueWork(()->{NitorEffects.install();FocusProjectileEffects.install();PortableHoleEffects.install();thaumcraft.blocks.MagicalLeavesBlock.silverSparkle=p->FollowingItemEffects.sparkle(p,2,7,0);for(var block:java.util.List.of(R3Content.GREATWOOD_LEAVES,R3Content.SILVERWOOD_LEAVES,R3Content.GREATWOOD_SAPLING,R3Content.SILVERWOOD_SAPLING,R3Content.SHIMMERLEAF))net.minecraft.client.renderer.ItemBlockRenderTypes.setRenderLayer(block.get(),net.minecraft.client.renderer.RenderType.cutout());});}
    @SubscribeEvent public static void leafColors(RegisterColorHandlersEvent.Block event){
        event.register((state,level,pos,tint)->0x8899aa,R3Content.SILVERWOOD_LEAVES.get());
        event.register((state,level,pos,tint)->level!=null&&pos!=null?net.minecraft.client.renderer.BiomeColors.getAverageFoliageColor(level,pos):net.minecraft.world.level.FoliageColor.getDefaultColor(),R3Content.GREATWOOD_LEAVES.get());
    }
    @SubscribeEvent public static void leafItemColors(RegisterColorHandlersEvent.Item event){
        event.register((stack,tint)->0x8899aa,R3Content.SILVERWOOD_LEAVES.get().asItem());
        event.register((stack,tint)->net.minecraft.world.level.FoliageColor.getDefaultColor(),R3Content.GREATWOOD_LEAVES.get().asItem());
    }
    @SubscribeEvent public static void screens(RegisterMenuScreensEvent event) { event.register(R3Content.FURNACE_MENU.get(), AlchemyFurnaceScreen::new);event.register(R3Content.THAUMATORIUM_MENU.get(),ThaumatoriumScreen::new);event.register(R3Content.HARNESS_MENU.get(),HarnessScreen::new); }
    @SubscribeEvent public static void itemColors(RegisterColorHandlersEvent.Item event) {
        event.register((stack,layer)->stack.getItem() instanceof thaumcraft.items.AspectDiscountRingItem ring?0xff000000|ring.aspect().getColor():-1,thaumcraft.registry.R5Content.DISCOUNT_RINGS.stream().map(java.util.function.Supplier::get).toArray(net.minecraft.world.item.Item[]::new));
        event.register((stack,layer)->{var focus=thaumcraft.items.WandFocus.get(stack);return focus.getItem() instanceof thaumcraft.api.wands.ItemFocusBasic item?0xff000000|item.getFocusColor(focus):0xffffffff;},thaumcraft.registry.R3Equipment.WAND.get(),thaumcraft.registry.R3Equipment.STAFF.get());
        event.register((stack,layer)->layer==0?0xff000000|(stack.getItem() instanceof thaumcraft.items.ThaumicArmorItem armor&&armor.kind()==thaumcraft.items.ThaumicArmorItem.Kind.VOID_ROBE?6961280:net.minecraft.world.item.component.DyedItemColor.getOrDefault(stack,6961280)):0xffffffff,thaumcraft.registry.R3Equipment.ARMOR.entrySet().stream().filter(e->e.getKey().startsWith("thaumaturge_")||e.getKey().startsWith("void_robe_")).map(e->e.getValue().get()).toArray(net.minecraft.world.item.Item[]::new));
        event.register((stack, layer) -> { var aspect = R3Content.aspect(stack); return layer == 1 && aspect != null ? 0xff000000 | aspect.getColor() : -1; }, R3Content.ESSENTIA_PHIAL.get(), R3Content.ESSENTIA_CRYSTAL.get(), R3Content.JAR_LABEL.get());
    }
    @SubscribeEvent public static void extensions(RegisterClientExtensionsEvent event){event.registerItem(new WandClientEffects(),thaumcraft.registry.R3Equipment.WAND.get(),thaumcraft.registry.R3Equipment.STAFF.get(),thaumcraft.registry.R3Equipment.SCEPTRE.get());event.registerItem(new ArmorClientExtensions(),thaumcraft.registry.R3Equipment.ARMOR.values().stream().map(java.util.function.Supplier::get).toArray(net.minecraft.world.item.Item[]::new));}
    @SubscribeEvent public static void arrows(EntityRenderersEvent.RegisterRenderers e){e.registerEntityRenderer(thaumcraft.entities.R3Entities.PRIMAL_ARROW.get(),PrimalArrowRenderer::new);}
    @SubscribeEvent public static void boneBow(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent e){e.enqueueWork(()->net.minecraft.client.renderer.item.ItemProperties.register(thaumcraft.registry.R3Equipment.BONE_BOW.get(),net.minecraft.resources.ResourceLocation.parse("thaumcraft:draw_stage"),(stack,level,user,seed)->{if(user==null||user.getUseItem()!=stack)return 0;int ticks=stack.getUseDuration(user)-user.getUseItemRemainingTicks();return ticks>=13?3:ticks>7?2:ticks>0?1:0;}));}
    private R3Client() {}
    @SubscribeEvent public static void ancientLootModels(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent event){event.enqueueWork(()->{for(var item:java.util.List.of(thaumcraft.registry.R5Content.URN_ITEM,thaumcraft.registry.R5Content.CRATE_ITEM))net.minecraft.client.renderer.item.ItemProperties.register(item.get(),net.minecraft.resources.ResourceLocation.parse("thaumcraft:loot_rarity"),(stack,level,entity,seed)->stack.getOrDefault(net.minecraft.core.component.DataComponents.BLOCK_STATE,net.minecraft.world.item.component.BlockItemStateProperties.EMPTY).apply(item.get().getBlock().defaultBlockState()).getValue(thaumcraft.blocks.AncientLootBlock.RARITY));});}
}
